+                !value.contains("trigger") || !value["trigger"].is_string() || !value.contains("text") ||
+                !value["text"].is_string()) {
+                valid = false;
+                break;
+            }
+            AgentSkill skill{value["name"].get<std::string>(), value["trigger"].get<std::string>(),
+                             value["text"].get<std::string>()};
+            if (!valid_skill_word_list(skill.name, '-') || !valid_skill_word_list(skill.trigger, '_') ||
